#include <bits/stdc++.h>
using namespace std;
class Solution {public:int minOperations(vector<int>& nums,int target){long long sum=0;long long cnt[32]={};for(int x:nums){sum+=x;++cnt[__builtin_ctz((unsigned)x)];}if(sum<target)return -1;int ans=0;for(int i=0;i<31;++i){if((target>>i)&1){if(!cnt[i]){int j=i+1;while(j<32&&!cnt[j])++j;while(j>i){--cnt[j];cnt[j-1]+=2;--j;++ans;}}--cnt[i];}cnt[i+1]+=cnt[i]/2;}return ans;}};
